const CENTRAL_BOARD_ID = "18418191275";
const pages = $input.all().map(item => item.json);
const firstBoard = pages.find(page => page.data?.boards?.[0])?.data?.boards?.[0];
if (!firstBoard) throw new Error("Board central nao encontrado: " + CENTRAL_BOARD_ID);
const itemsById = new Map();
for (const page of pages) {
  const board = page.data?.boards?.[0];
  for (const item of board?.items_page?.items || []) itemsById.set(String(item.id), item);
}
const formatBoardName = (date) => {
  const mm = String(date.getMonth() + 1).padStart(2, "0");
  const yy = String(date.getFullYear()).slice(-2);
  return `${mm}/${yy} - Plan. de Intermitente - Contato`;
};
const now = new Date();
const currentMonth = new Date(now.getFullYear(), now.getMonth(), 1);
const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
const _ym = (d) => d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0');
return [{
  json: {
    centralBoardId: CENTRAL_BOARD_ID,
    competenciaAtual: _ym(currentMonth),
    competenciaProxima: _ym(nextMonth),
    currentBoardName: firstBoard.name,
    archiveBoardName: formatBoardName(currentMonth),
    nextBoardName: formatBoardName(nextMonth),
    itemIdsToArchive: Array.from(itemsById.keys()),
    itemCountToArchive: itemsById.size,
    itemPagesRead: pages.length
  }
}];

const TARGET_BOARD_ID = "18418191275";
const TARGET_GROUP_ID = "group_mm2eqsdr"; // NAO CONVOCADOS
const BATCH_SIZE = 25;

const formatDate = (value) => {
  if (!value) return "";
  const s = String(value).trim();
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return `${iso[3]}/${iso[2]}/${iso[1]}`;
  const br = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (br) return `${br[1]}/${br[2]}/${br[3]}`;
  return s.substring(0, 10);
};

// Atestado: somente periodos que tocam o MES CORRENTE (01 ao ultimo dia)
const parseBR = (s) => {
  const m = String(s || "").match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null;
};
const atestadoMesCorrente = (raw) => {
  if (!raw) return "";
  const now = new Date();
  const ws = new Date(now.getFullYear(), now.getMonth(), 1);
  const we = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return String(raw).split(";").map(s => s.trim()).filter(Boolean).filter(p => {
    const parts = p.split(" a ");
    const ini = parseBR(parts[0]);
    const fim = parseBR(parts[1] || parts[0]);
    return ini && fim && ini <= we && fim >= ws;
  }).join("; ");
};

const normalize = (value) => String(value || "")
  .normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/\s+/g, " ").trim().toUpperCase();
const getValue = (data, names) => {
  for (const nm of names) for (const [k, v] of Object.entries(data))
    if (normalize(k) === nm && v !== undefined && v !== null && String(v).trim() !== "") return v;
  return "";
};
const employeeName = (data) => getValue(data, ["NOME DO FUNCIONARIO", "FUNCIONARIO"]) || "Sem nome";

const collaborators = [];
for (const item of $input.all()) {
  const data = item.json;
  if (normalize(getValue(data, ["INTERMITENTE?"])) !== "SIM") continue;
  const nome = employeeName(data);
  const columnValues = {
    "dropdown_mktadatt": { "labels": [nome] },
    "texto": getValue(data, ["FUNCIONARIO", "NOME DO FUNCIONARIO"]),
    "dup__of_matr_cula": getValue(data, ["CPF"]),
    "texto75": getValue(data, ["LOCAL/UNIDADE"]),
    "text_mkrzbj02": getValue(data, ["CAMPO COMPLEMENTAR"]),
    "text_mkrztp4t": getValue(data, ["JORNADA"]),
    "texto0": getValue(data, ["FUNCAO"]),
    "text_mkzh8jhn": formatDate(getValue(data, ["ADMISSAO"])),
    "text_mkt63tyk": getValue(data, ["CODIGO"]),
    "texto9": atestadoMesCorrente(getValue(data, ["PERIODO DO ATESTADO"])),
    "optante___vt": { "label": getValue(data, ["VALE TRANSPORTE"]) || "NÃO" }
  };
  collaborators.push({ groupId: TARGET_GROUP_ID, itemName: "INTERMITENTE", columnValuesString: JSON.stringify(columnValues) });
}

const output = [];
for (let start = 0; start < collaborators.length; start += BATCH_SIZE) {
  const batch = collaborators.slice(start, start + BATCH_SIZE);
  const declarations = ["$boardId: ID!"];
  const mutations = ["complexity { before after query }"];
  const variables = { boardId: TARGET_BOARD_ID };
  batch.forEach((c, i) => {
    declarations.push(`$groupId${i}: String!`, `$itemName${i}: String!`, `$columnValues${i}: JSON!`);
    mutations.push(`item${i}: create_item(board_id: $boardId, group_id: $groupId${i}, item_name: $itemName${i}, column_values: $columnValues${i}, create_labels_if_missing: true) { id }`);
    variables[`groupId${i}`] = c.groupId;
    variables[`itemName${i}`] = c.itemName;
    variables[`columnValues${i}`] = c.columnValuesString;
  });
  output.push({ json: { batchNumber: output.length + 1, batchSize: batch.length, totalCollaborators: collaborators.length, query: `mutation CreateIntermitentesBatch(${declarations.join(", ")}) { ${mutations.join(" ")} }`, variables } });
}
return output;

// Piso de sanidade ANTES de qualquer passo destrutivo.
// Em 14/07/2026 a ponte caiu, a lista voltou vazia e a virada seguiu: arquivou os 181
// itens, renomeou o board e criou ZERO intermitentes. O mes novo nasceu vazio com o
// resumo dizendo ok:true. Este no existe para isso nao se repetir.
const PISO = 100; // medido 08/08/2026: 137 intermitentes no BENAUT
const lotes = $input.all();
const total = lotes.reduce((s, i) => s + (i.json.batchSize || 0), 0);
const ok = total >= PISO;
return [{ json: {
  ok, total, piso: PISO, lotes: lotes.length,
  motivo: ok ? null : `lista de intermitentes veio com ${total} (piso ${PISO}) — RM instavel ou consulta mudou`,
} }];

